<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Search, Plus, Minus, ShoppingBag, Trash2, CheckCircle2, ArrowRight } from '@lucide/vue'
import { api, list, money } from '../api'
import type { Category, Dish, Order } from '../types'
import DishArt from '../components/DishArt.vue'
import AppModal from '../components/AppModal.vue'
const categories = ref<Category[]>([]), dishes = ref<Dish[]>([]), category = ref(0), search = ref(''), table = ref(''), waiter = ref(''), mode = ref('quick'), error = ref(''), busy = ref(false), payModal = ref(false), payment = ref('cash'), result = ref<Order>(), cashGiven = ref('')
const cart = ref<{dish: Dish; quantity: number; note: string}[]>([]), cartPanel = ref<HTMLElement>()
const key = ref(crypto.randomUUID()), lockedPayload = ref<string>()
const total = computed(() => cart.value.reduce((sum,l) => sum + Math.round(Number(l.dish.price)*100)*l.quantity,0)/100)
const filtered = computed(() => dishes.value.filter(d=>!d.archived && (!category.value||d.category===category.value) && d.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))
const change = computed(() => Math.max(0, Number(cashGiven.value) - total.value))
onMounted(async()=>{try { [categories.value,dishes.value]=await Promise.all([list<Category>('categories/'),list<Dish>('dishes/')]) } catch(e){error.value=(e as Error).message}})
watch([cart,table,waiter,mode],()=>{if (!lockedPayload.value) key.value=crypto.randomUUID()}, {deep:true})
function add(dish: Dish) {if(busy.value||lockedPayload.value||!dish.available)return; const line=cart.value.find(l=>l.dish.id===dish.id); if(line)line.quantity=Math.min(999,line.quantity+1); else cart.value.push({dish,quantity:1,note:''}); result.value=undefined}
function adjust(id:number, amount:number) {if(lockedPayload.value)return; const line=cart.value.find(l=>l.dish.id===id); if(!line)return; line.quantity+=amount; if(line.quantity<=0)cart.value=cart.value.filter(l=>l.dish.id!==id)}
async function submit(method: string) {if(busy.value)return; busy.value=true;error.value=''; try {if(!lockedPayload.value) lockedPayload.value=JSON.stringify({key:key.value,table:mode.value==='table'?table.value:'',waiter:mode.value==='table'?waiter.value:'',payment_method:method,lines:cart.value.map(l=>({dish:l.dish.id,quantity:l.quantity,note:l.note}))}); result.value=await api<Order>('orders/',{method:'POST',body:lockedPayload.value}); lockedPayload.value=undefined; cart.value=[]; key.value=crypto.randomUUID(); payModal.value=false; cashGiven.value='' } catch(e) { error.value=(e as Error).message; /* Keep the same payload/key after uncertain network outcomes. */ } finally{busy.value=false} }
function unlock() { if(confirm('Avval Buyurtmalar sahifasida bu hisob saqlanmaganini tekshiring. Tekshirdingizmi?')) {lockedPayload.value=undefined;key.value=crypto.randomUUID();error.value=''} }
function scrollToCart() { cartPanel.value?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
</script>
<template><div class="page-heading"><div><span class="eyebrow">SAVDO ISH JOYI</span><h1>Kassa<span class="heading-dot">.</span></h1><p>Taomni tanlang. Hisobni tizim hisoblaydi.</p></div><RouterLink to="/orders" class="button secondary">To‘lov kutilmoqda <ArrowRight :size="16"/></RouterLink></div><p v-if="error" class="alert error">{{ error }}</p><div v-if="result" class="alert success"><CheckCircle2 :size="20"/><span>#{{ result.id }} buyurtma {{ result.status==='paid'?'to‘landi':'to‘lov kutilmoqda bo‘limiga yuborildi' }} · {{ money(result.total) }} so‘m.</span><RouterLink to="/orders">Chekni ochish →</RouterLink></div><div class="pos-layout"><section><div class="search-field wide"><Search :size="19"/><input v-model="search" placeholder="Taom nomini yozing…" aria-label="Taom qidirish"></div><div class="tabs pos-tabs"><button :class="{selected:!category}" @click="category=0">Barchasi</button><button v-for="c in categories" :key="c.id" :class="{selected:category===c.id}" @click="category=c.id">{{ c.name }}</button></div><div class="pos-dishes"><button v-for="dish in filtered" :key="dish.id" class="pos-dish" :disabled="!dish.available||busy||!!lockedPayload" @click="add(dish)"><DishArt :name="dish.name" :category="dish.category_name" :image="dish.image"/><div><span>{{ dish.portion }}</span><h3>{{ dish.name }}</h3><footer><strong>{{ money(dish.price) }} <small>so‘m</small></strong><span class="add-circle"><Plus :size="17"/></span></footer><small v-if="!dish.available">Hozir mavjud emas</small></div></button></div></section><aside ref="cartPanel" class="cart panel"><header class="cart-header"><div><ShoppingBag :size="20"/><h2>Joriy buyurtma</h2></div><span class="pill">{{ cart.reduce((s,l)=>s+l.quantity,0) }} ta</span></header><div class="segmented"><button :class="{selected:mode==='quick'}" :disabled="!!lockedPayload" @click="mode='quick'">Tezkor savdo</button><button :class="{selected:mode==='table'}" :disabled="!!lockedPayload" @click="mode='table'">Stolga xizmat</button></div><div v-if="mode==='table'" class="form-row table-fields"><label>Stol<input v-model="table" :disabled="!!lockedPayload" maxlength="40" placeholder="Masalan, 4"></label><label>Ofitsiant<input v-model="waiter" :disabled="!!lockedPayload" maxlength="100" placeholder="Ism"></label></div><div v-if="!cart.length" class="empty-cart"><ShoppingBag :size="45" :stroke-width="1"/><h3>Buyurtma hali bo‘sh</h3><p>Chap tomondan taomlarni tanlang.</p></div><div class="cart-lines"><div v-for="line in cart" :key="line.dish.id" class="cart-line"><div class="cart-line-top"><strong>{{ line.dish.name }}</strong><button class="icon-button" :disabled="!!lockedPayload" :aria-label="`${line.dish.name} olib tashlash`" @click="adjust(line.dish.id,-line.quantity)"><Trash2 :size="15"/></button></div><div class="cart-line-bottom"><div class="stepper"><button :disabled="busy||!!lockedPayload" @click="adjust(line.dish.id,-1)" aria-label="Kamaytirish"><Minus :size="13"/></button><span>{{ line.quantity }}</span><button :disabled="busy||!!lockedPayload||line.quantity>=999" @click="adjust(line.dish.id,1)" aria-label="Ko‘paytirish"><Plus :size="13"/></button></div><strong>{{ money(Number(line.dish.price)*line.quantity) }}</strong></div><input v-model="line.note" :disabled="!!lockedPayload" class="line-note" maxlength="200" placeholder="Oshxona uchun izoh…"></div></div><footer class="cart-footer"><div class="cart-total"><span>Jami</span><strong>{{ money(total) }} <small>so‘m</small></strong></div><small class="muted">Xizmat haqi va soliq qoidalari hali ulanmagan.</small><template v-if="lockedPayload"><button class="button primary full" :disabled="busy" @click="submit(payment)">Oldingi amalni qayta tekshirish</button><button class="button secondary full" :disabled="busy" @click="unlock">Hisobni tekshirdim, tahrirlash</button></template><template v-else><button class="button primary full" :disabled="!cart.length||busy||(mode==='table'&&!table.trim())" @click="submit('')">Buyurtmani yuborish <ArrowRight :size="17"/></button><small class="muted">Buyurtma oshxonaga yuboriladi. Mijoz ovqatlangach, to‘lovni «To‘lov kutilmoqda» bo‘limidan qayd eting.</small><button class="button secondary full" :disabled="!cart.length||busy||(mode==='table'&&!table.trim())" @click="payModal=true; cashGiven=String(total)">Darhol to‘lov olish</button></template></footer></aside></div><button v-if="cart.length" class="mobile-cart-cta" @click="scrollToCart"><span><ShoppingBag :size="17"/> {{ cart.reduce((sum, line) => sum + line.quantity, 0) }} ta buyurtma</span><strong>{{ money(total) }} →</strong></button><AppModal :open="payModal" title="To‘lovni qayd etish" @close="!busy && (payModal=false)"><div class="payment-amount">{{ money(total) }} <small>so‘m</small></div><form @submit.prevent="submit(payment)"><label>To‘lov usuli<select v-model="payment" :disabled="!!lockedPayload"><option value="cash">Naqd</option><option value="card">Terminal orqali karta</option></select></label><template v-if="payment==='cash'"><label>Berilgan naqd<input v-model="cashGiven" type="number" :min="total" step="0.01" required></label><p class="change-line">Qaytim <strong>{{ money(change) }} so‘m</strong></p></template><p v-else class="alert">Faqat terminalda to‘lov muvaffaqiyatli o‘tganidan keyin qayd eting. Terminal integratsiyasi hali ulanmagan.</p><p v-if="error" class="alert error">{{ error }}</p><button class="button primary full" :disabled="busy">{{ busy?'Saqlanmoqda…':'To‘lovni tasdiqlash' }}</button></form></AppModal></template>
